import{_ as s,o as a,c as i,a2 as t}from"./chunks/framework.DbIb1qZn.js";const k=JSON.parse('{"title":"Install","description":"Install the frensense binary with Cargo, npm, or a release download.","frontmatter":{"title":"Install","description":"Install the frensense binary with Cargo, npm, or a release download."},"headers":[],"relativePath":"guide/installation.md","filePath":"guide/installation.md"}'),n={name:"guide/installation.md"};function l(r,e,d,h,o,p){return a(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to &quot;Install&quot;">​</a></h1><p>Frensense is one binary named <code>frensense</code>. Pick the route that fits your machine, then run <code>frensense --version</code> to check it worked.</p><table tabindex="0"><thead><tr><th>Route</th><th>Needs</th><th>Command</th></tr></thead><tbody><tr><td>npm</td><td>Node.js 18 or newer</td><td><code>npm install -g @friehub/frensense</code></td></tr><tr><td>No install</td><td>Node.js 18 or newer</td><td><code>npx @friehub/frensense .</code></td></tr><tr><td>Cargo</td><td>Rust 1.95 or newer</td><td><code>cargo install frensense</code></td></tr><tr><td>Release download</td><td>nothing</td><td>see below</td></tr></tbody></table><h2 id="npm" tabindex="-1">npm <a class="header-anchor" href="#npm" aria-label="Permalink to &quot;npm&quot;">​</a></h2><p>The npm package carries prebuilt binaries, so you do not need a Rust compiler. It supports Linux x64, macOS (Intel and Apple Silicon) and Windows x64.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @friehub/frensense</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">frensense</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><p>The <code>frensense</code> command from npm is a small launcher around the native binary. Every subcommand (<code>watch</code>, <code>mcp</code>, <code>lsp</code>, ...) works the same way.</p><h2 id="cargo" tabindex="-1">Cargo <a class="header-anchor" href="#cargo" aria-label="Permalink to &quot;Cargo&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> frensense</span></span></code></pre></div><p>This compiles the binary and puts it in <code>~/.cargo/bin</code>. It needs Rust 1.95 or newer, and takes a few minutes.</p><h2 id="release-download" tabindex="-1">Release download <a class="header-anchor" href="#release-download" aria-label="Permalink to &quot;Release download&quot;">​</a></h2><p>Each <a href="https://github.com/Friehub/frensense-v2/releases" target="_blank" rel="noreferrer">GitHub release</a> attaches one binary per platform, named after its Rust target:</p><table tabindex="0"><thead><tr><th>Platform</th><th>File</th></tr></thead><tbody><tr><td>Linux x64</td><td><code>frensense-x86_64-unknown-linux-gnu</code></td></tr><tr><td>macOS Intel</td><td><code>frensense-x86_64-apple-darwin</code></td></tr><tr><td>macOS Apple Silicon</td><td><code>frensense-aarch64-apple-darwin</code></td></tr><tr><td>Windows x64</td><td><code>frensense-x86_64-pc-windows-msvc.exe</code></td></tr></tbody></table><p>There is no Linux arm64 build yet. On Linux x64:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -L</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> frensense</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  https://github.com/Friehub/frensense-v2/releases/latest/download/frensense-x86_64-unknown-linux-gnu</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +x</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> frensense</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> frensense</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/local/bin/</span></span></code></pre></div><p>Releases are built by a GitHub Actions workflow that also produces a SLSA provenance file (<code>*.intoto.jsonl</code>) for the binaries. You can check a download against it with <a href="https://github.com/slsa-framework/slsa-verifier" target="_blank" rel="noreferrer">slsa-verifier</a>.</p><h2 id="check-the-install" tabindex="-1">Check the install <a class="header-anchor" href="#check-the-install" aria-label="Permalink to &quot;Check the install&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">frensense</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # prints: frensense 0.8.0</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">frensense</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --help</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # lists every flag and subcommand</span></span></code></pre></div><p>If a scan ends with <code>Status: Failed analysis</code> and a warning about &quot;unsupported or absent source input&quot;, the folder holds no <a href="/guide/#what-it-scans">supported files</a>. Try it inside a project that has a <code>.py</code>, <code>.ts</code>, <code>.js</code>, <code>.go</code>, <code>.rs</code> or <code>.c</code> file.</p><h2 id="build-from-source" tabindex="-1">Build from source <a class="header-anchor" href="#build-from-source" aria-label="Permalink to &quot;Build from source&quot;">​</a></h2><p>Only needed if you want to change the engine:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/Friehub/frensense-v2.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> frensense-v2</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --release</span></span></code></pre></div><p>The binary is <code>target/release/frensense</code>. See <a href="https://github.com/Friehub/frensense-v2/blob/main/CONTRIBUTING.md" target="_blank" rel="noreferrer">CONTRIBUTING.md</a> before opening a pull request.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><p><a href="/guide/first-scan">Run your first scan</a>.</p>`,25)])])}const u=s(n,[["render",l]]);export{k as __pageData,u as default};
